-- ------------------------------------------------------------------
-- MovieLinkBD database schema (MySQL 8+ / MariaDB 10.6+)
-- Generated by `php bin/console.php migrate`. Safe to run repeatedly.
-- ------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS titles (
    id            BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    slug          VARCHAR(191) NOT NULL UNIQUE,
    title         VARCHAR(255) NOT NULL,
    type          ENUM('movie','series','anime','drama','animation') NOT NULL DEFAULT 'movie',
    year          SMALLINT NULL,
    quality       VARCHAR(40) NULL,
    language      VARCHAR(60) NULL,
    language_raw  VARCHAR(120) NULL,
    languages     VARCHAR(191) NULL,
    rating        DECIMAL(3,1) NULL,
    views         BIGINT UNSIGNED NOT NULL DEFAULT 0,
    poster        VARCHAR(500) NULL,
    ep_label      VARCHAR(80) NULL,
    ep_state      ENUM('added','completed','part') NULL,
    status        ENUM('completed','ongoing','upcoming') NOT NULL DEFAULT 'completed',
    synopsis      TEXT NULL,
    runtime       VARCHAR(40) NULL,
    ott_slug      VARCHAR(60) NULL,
    is_pinned     TINYINT(1) NOT NULL DEFAULT 0,
    is_adult      TINYINT(1) NOT NULL DEFAULT 0,
    is_new        TINYINT(1) NOT NULL DEFAULT 0,
    is_upcoming   TINYINT(1) NOT NULL DEFAULT 0,
    release_date  DATE NULL,
    created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_titles_type (type),
    INDEX idx_titles_lang (language),
    INDEX idx_titles_views (views DESC),
    INDEX idx_titles_updated (updated_at DESC),
    INDEX idx_titles_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS genres (
    id   INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    slug VARCHAR(60) NOT NULL UNIQUE,
    name VARCHAR(80) NOT NULL,
    icon VARCHAR(16) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS title_genres (
    title_id BIGINT UNSIGNED NOT NULL,
    genre_id INT UNSIGNED NOT NULL,
    PRIMARY KEY (title_id, genre_id),
    INDEX idx_title_genres_genre (genre_id),
    CONSTRAINT fk_tg_title FOREIGN KEY (title_id) REFERENCES titles (id) ON DELETE CASCADE,
    CONSTRAINT fk_tg_genre FOREIGN KEY (genre_id) REFERENCES genres (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS collections (
    id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    slug        VARCHAR(120) NOT NULL UNIQUE,
    name        VARCHAR(160) NOT NULL,
    description VARCHAR(500) NULL,
    keywords    VARCHAR(500) NULL,
    sort        INT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS collection_items (
    collection_id INT UNSIGNED NOT NULL,
    title_id      BIGINT UNSIGNED NOT NULL,
    sort          INT NOT NULL DEFAULT 0,
    PRIMARY KEY (collection_id, title_id),
    CONSTRAINT fk_ci_collection FOREIGN KEY (collection_id) REFERENCES collections (id) ON DELETE CASCADE,
    CONSTRAINT fk_ci_title FOREIGN KEY (title_id) REFERENCES titles (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS ott_platforms (
    id   INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    slug VARCHAR(60) NOT NULL UNIQUE,
    name VARCHAR(80) NOT NULL,
    logo VARCHAR(500) NULL,
    sort INT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS download_links (
    id       BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    title_id BIGINT UNSIGNED NOT NULL,
    label    VARCHAR(120) NOT NULL,
    quality  VARCHAR(40) NULL,
    size     VARCHAR(40) NULL,
    url      VARCHAR(700) NOT NULL,
    sort     INT NOT NULL DEFAULT 0,
    INDEX idx_links_title (title_id, sort),
    CONSTRAINT fk_dl_title FOREIGN KEY (title_id) REFERENCES titles (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS episodes (
    id          BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    title_id    BIGINT UNSIGNED NOT NULL,
    season      SMALLINT NOT NULL DEFAULT 1,
    episode     SMALLINT NOT NULL,
    name        VARCHAR(160) NULL,
    released_at DATE NULL,
    UNIQUE KEY uq_episode (title_id, season, episode),
    CONSTRAINT fk_ep_title FOREIGN KEY (title_id) REFERENCES titles (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS notices (
    id      INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    message VARCHAR(500) NOT NULL,
    style   VARCHAR(30) NOT NULL DEFAULT 'new',
    color   VARCHAR(20) NOT NULL DEFAULT '#2ad99a',
    active  TINYINT(1) NOT NULL DEFAULT 1,
    sort    INT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS pages (
    id         INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    slug       VARCHAR(120) NOT NULL UNIQUE,
    title      VARCHAR(160) NOT NULL,
    body       MEDIUMTEXT NOT NULL,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS settings (
    `key` VARCHAR(120) PRIMARY KEY,
    value TEXT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS api_endpoints (
    id        INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    method    VARCHAR(8) NOT NULL DEFAULT 'GET',
    path      VARCHAR(191) NOT NULL UNIQUE,
    category  VARCHAR(40) NOT NULL DEFAULT 'core',
    summary   VARCHAR(255) NOT NULL,
    params    TEXT NULL,
    sample    TEXT NULL,
    is_public TINYINT(1) NOT NULL DEFAULT 1,
    sort      INT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS api_logs (
    id          BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    method      VARCHAR(8) NOT NULL,
    path        VARCHAR(191) NOT NULL,
    status      SMALLINT NOT NULL,
    duration_ms INT NOT NULL DEFAULT 0,
    ip          VARCHAR(45) NULL,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_api_logs_created (created_at DESC)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
